//! ✉️ The complete Semio union admits every authored layout and its selected root cells.
use super::{SemioSnapshot,ValueError,ValueRefusalKind};
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::SqliteDatabaseLimits};
fn add(a:usize,b:usize)->Result<usize,ValueError>{a.checked_add(b).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"Semio union semantic cell extent overflow"))}
/// 🏛️ Validates every selected and unselected authored table before native ownership.
pub(super)fn layout(limits:SqliteDatabaseLimits)->Result<(),ValueError>{
 let mut bytes=0;for statement in SemioSnapshot::SQLITE_SCHEMA.split(';'){bytes=add(bytes,statement.trim().len())?;}
 for name in ["semio_animation_channel","semio_animation_document","semio_animation_keyframe","semio_animation_quaternion","semio_animation_scalar","semio_animation_timeline","semio_animation_vector3","semio_animation_weight","semio_audio_channel","semio_audio_document","semio_audio_sample","semio_audio_tag","semio_base_document","semio_brep_coedge","semio_brep_curve2","semio_brep_curve2_knot","semio_brep_curve2_point","semio_brep_curve2_weight","semio_brep_curve3","semio_brep_curve3_knot","semio_brep_curve3_point","semio_brep_curve3_weight","semio_brep_document","semio_brep_edge","semio_brep_face","semio_brep_inner_loop","semio_brep_loop","semio_brep_loop_edge","semio_brep_shell","semio_brep_shell_face","semio_brep_solid","semio_brep_solid_shell","semio_brep_surface","semio_brep_surface_knot_u","semio_brep_surface_knot_v","semio_brep_surface_point","semio_brep_surface_weight","semio_brep_vertex","semio_cad_arc","semio_cad_block","semio_cad_circle","semio_cad_dimension","semio_cad_document","semio_cad_ellipse","semio_cad_entity","semio_cad_insert","semio_cad_layer","semio_cad_line","semio_cad_polyline","semio_cad_polyline_vertex","semio_cad_solid","semio_cad_text","semio_document_block","semio_document_code","semio_document_collection","semio_document_document","semio_document_heading","semio_document_image","semio_document_image_block","semio_document_list","semio_document_list_item","semio_document_member","semio_document_page_break","semio_document_paragraph","semio_document_quote","semio_document_run","semio_document_style","semio_document_table","semio_document_table_cell","semio_document_table_row","semio_drawing_arc","semio_drawing_child","semio_drawing_close","semio_drawing_cubic","semio_drawing_document","semio_drawing_group","semio_drawing_image","semio_drawing_layer","semio_drawing_line","semio_drawing_move","semio_drawing_node","semio_drawing_path","semio_drawing_quad","semio_drawing_segment","semio_drawing_style","semio_drawing_text","semio_flow_document","semio_flow_edge","semio_flow_node","semio_flow_parameter","semio_graph_document","semio_graph_edge","semio_graph_edge_property","semio_graph_list_element","semio_graph_map_entry","semio_graph_node","semio_graph_port","semio_graph_port_property","semio_graph_property","semio_graph_value","semio_image_document","semio_image_frame","semio_image_metadata","semio_image_sample","semio_kit_blob","semio_kit_connection","semio_kit_design","semio_kit_document","semio_kit_model_child","semio_kit_object_child","semio_kit_piece","semio_kit_reference","semio_kit_representation","semio_kit_type","semio_kit_value_child","semio_mesh_color","semio_mesh_document","semio_mesh_index","semio_mesh_material","semio_mesh_mesh","semio_mesh_normal","semio_mesh_position","semio_mesh_primitive","semio_mesh_texture","semio_mesh_uv","semio_model_document","semio_model_element","semio_model_entity","semio_model_geometry_reference","semio_model_placement","semio_model_property","semio_model_property_set","semio_model_relation","semio_model_spatial","semio_object_brep_child","semio_object_document","semio_object_mesh_child","semio_object_reference","semio_object_value_child","semio_presentation_block","semio_presentation_code","semio_presentation_collection","semio_presentation_document","semio_presentation_heading","semio_presentation_image_block","semio_presentation_layout","semio_presentation_list","semio_presentation_list_item","semio_presentation_master","semio_presentation_member","semio_presentation_page_break","semio_presentation_paragraph","semio_presentation_picture","semio_presentation_placeholder","semio_presentation_quote","semio_presentation_run","semio_presentation_shape","semio_presentation_shape_table","semio_presentation_shape_table_cell","semio_presentation_shape_table_row","semio_presentation_slide","semio_presentation_table","semio_presentation_table_cell","semio_presentation_table_row","semio_presentation_text_box","semio_table_cell","semio_table_column","semio_table_document","semio_table_list_element","semio_table_map_entry","semio_table_row","semio_table_value","semio_text_document","semio_text_mark","semio_text_run","semio_value_document","semio_value_list_element","semio_value_map_entry","semio_value_node","semio_value_value","semio_video_document","semio_video_sample","semio_video_stream"] {bytes=add(bytes,name.len())?;}
 if bytes.max(SemioSnapshot::SQLITE_SCHEMA.len())>limits.max_schema_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"Semio union complete schema exceeds caller bytes"))}
 if limits.max_tables<183||limits.max_columns<54||limits.max_rows<2{return Err(ValueError::new(ValueRefusalKind::WorkLimit,"Semio union complete authored layout exceeds copied limits"))}Ok(())
}
/// 🧮️ Reserves the exact root row while preserving all child entity limits.
pub(super)fn subset_limits(mut limits:SqliteDatabaseLimits,schema_bytes:usize,tag:&str)->Result<SqliteDatabaseLimits,ValueError>{
 layout(limits)?;let bytes=add(add(16,schema_bytes)?,tag.len())?;
 limits.max_rows=limits.max_rows.checked_sub(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"Semio union root exceeds caller row limit"))?;
 limits.max_value_bytes=limits.max_value_bytes.checked_sub(bytes).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"Semio union root exceeds caller cell bytes"))?;Ok(limits)
}
/// 🏷️ Maps each authored binary ordinal to its relational discriminator.
pub(super)fn tag(ordinal:u8)->Result<&'static str,ValueError>{match ordinal{0=>Ok("brep"),1=>Ok("mesh"),2=>Ok("model"),3=>Ok("value"),4=>Ok("document"),5=>Ok("cad"),6=>Ok("drawing"),7=>Ok("image"),8=>Ok("video"),9=>Ok("audio"),10=>Ok("animation"),11=>Ok("presentation"),12=>Ok("flow"),13=>Ok("text"),14=>Ok("table"),15=>Ok("graph"),16=>Ok("object"),17=>Ok("kit"),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"unknown Semio native envelope subset ordinal"))}}
